#include <iostream>
#include <string>
#include <cctype>

int main() {
    std::string s;
    if (!std::getline(std::cin, s)) return 0;

    for (char &c : s) c = std::tolower(static_cast<unsigned char>(c));

    auto is_vowel = [](char c) {
        return c == 'a' || c == 'e' || c == 'i' || c == 'o' || c == 'u';
    };

    bool bad = false;

    for (size_t i = 0; i + 1 < s.size(); ++i) {
        if (!is_vowel(s[i]) && s[i] != 'n' &&
            !is_vowel(s[i + 1]) && s[i + 1] != 'n') {
            bad = true;
            break;
        }
    }

    if (!bad && !s.empty()) {
        char last = s.back();
        if (!is_vowel(last) && last != 'n') bad = true;
    }

    std::cout << (bad ? "NO" : "YES") << std::endl;
    return 0;
}

