#include <iostream>
#include <string>
#include <regex>
#include <algorithm>

int main() {
    std::string s;
    if (!std::getline(std::cin, s)) return 0;

    std::transform(s.begin(), s.end(), s.begin(), ::tolower);

    std::regex r1("[^aeioun][^aeiou]");
    std::regex r2("[^aeioun]$");

    if (std::regex_search(s, r1) || std::regex_search(s, r2))
        std::cout << "NO\n";
    else
        std::cout << "YES\n";

    return 0;
}
